class Solution {
  private static final int MAXV = 100_001;

  private static void updateMax(long[] bit, int i, long v) {
    for (; i <= MAXV; i += i & -i) bit[i] = Math.max(bit[i], v);
  }

  private static long queryMax(long[] bit, int i) {
    long r = 0;
    for (; i > 0; i -= i & -i) r = Math.max(r, bit[i]);
    return r;
  }

  public long maxAlternatingSum(int[] nums, int k) {
    int n = nums.length;
    long[] downByValue = new long[MAXV + 1], upByValueReversed = new long[MAXV + 1];
    long[] up = new long[n], down = new long[n];
    long best = 0;
    for (int i = 0; i < n; i++) {
      int j = i - k;
      if (j >= 0) {
        updateMax(downByValue, nums[j], down[j]);
        updateMax(upByValueReversed, MAXV - nums[j], up[j]);
      }
      up[i] = nums[i] + queryMax(downByValue, nums[i] - 1);
      down[i] = nums[i] + queryMax(upByValueReversed, MAXV - nums[i] - 1);
      best = Math.max(best, Math.max(up[i], down[i]));
    }
    return best;
  }
}
